using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageGenerationTests
{
    private const string Source = """
        using MessagePack;

        [MessagePackObject]
        public class IntKeyObject
        {
            [Key(0)]
            public int Number { get; set; }
        }

        [MessagePackObject(keyAsPropertyName: true)]
        public class StringKeyObject
        {
            public string Name { get; set; } = "";
        }

        public enum SampleEnum
        {
            Zero,
            One,
        }

        [MessagePackObject]
        public class EnumContainer
        {
            [Key(0)]
            public SampleEnum Value { get; set; }
        }

        [Union(0, typeof(Dog))]
        [Union(1, typeof(Cat))]
        public interface IAnimal
        {
        }

        [MessagePackObject]
        public class Dog : IAnimal
        {
            [Key(0)]
            public int Age { get; set; }
        }

        [MessagePackObject]
        public class Cat : IAnimal
        {
            [Key(0)]
            public string Name { get; set; } = "";
        }

        [MessagePackObject]
        public class AnimalContainer
        {
            [Key(0)]
            public IAnimal Animal { get; set; } = null!;
        }

        [GeneratedMessagePackResolver]
        public partial class TestResolver
        {
        }
        """;

        [Fact]
        public async Task EveryGeneratedClassIsDecoratedWithoutAnySetting()
        {
            CSharpCompilation compilation = await CreateCompilationAsync();
            (GeneratorDriverRunResult runResult, Compilation outputCompilation) = RunGenerator(compilation);
            AssertNoCompileErrors(outputCompilation);

            Assert.NotEmpty(runResult.GeneratedTrees);
            int inspectedClasses = 0;
            foreach (SyntaxTree tree in runResult.GeneratedTrees)
            {
                SyntaxNode root = await tree.GetRootAsync();
                foreach (ClassDeclarationSyntax declaration in root.DescendantNodes().OfType<ClassDeclarationSyntax>())
                {
                    inspectedClasses++;
                    Assert.True(
                        HasCoverageExclusion(declaration),
                        $"Generated class {declaration.Identifier.ValueText} in {tree.FilePath} has no ExcludeFromCodeCoverage attribute.");
                }
            }

            Assert.True(inspectedClasses > 0, "The generator did not produce any classes to inspect.");
        }

        [Fact]
        public async Task GeneratedCodeCompilesWhenAttributeIsUnavailable()
        {
            CSharpCompilation compilation = await CreateCompilationAsync("NETSTANDARD2_0");
            (_, Compilation outputCompilation) = RunGenerator(compilation);
            AssertNoCompileErrors(outputCompilation);
        }

        private static async Task<CSharpCompilation> CreateCompilationAsync(params string[] preprocessorSymbols)
        {
            var frameworkReferences = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
            var references = frameworkReferences.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
            var parseOptions = new CSharpParseOptions(LanguageVersion.CSharp12, preprocessorSymbols: preprocessorSymbols);
            return CSharpCompilation.Create(
                assemblyName: "CoverageExclusionReceipts",
                syntaxTrees: new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
                references: references,
                options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, nullableContextOptions: NullableContextOptions.Enable));
        }

        private static (GeneratorDriverRunResult RunResult, Compilation OutputCompilation) RunGenerator(CSharpCompilation compilation)
        {
            GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator());
            driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation outputCompilation, out var generatorDiagnostics);
            Assert.True(generatorDiagnostics.IsDefaultOrEmpty, string.Join(Environment.NewLine, generatorDiagnostics));
            return (driver.GetRunResult(), outputCompilation);
        }

        private static bool HasCoverageExclusion(ClassDeclarationSyntax declaration)
        {
            return declaration.AttributeLists
                .SelectMany(list => list.Attributes)
                .Any(attribute => attribute.Name.ToString() == "global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage");
        }

        private static void AssertNoCompileErrors(Compilation compilation)
        {
            Diagnostic[] errors = compilation.GetDiagnostics().Where(diagnostic => diagnostic.Severity == DiagnosticSeverity.Error).ToArray();
            Assert.True(errors.Length == 0, string.Join(Environment.NewLine, errors));
        }
}

