using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class NetFrameworkExcludeFromCodeCoverageTests
{
    [Fact]
    public async Task AllGeneratedTypesAreDecoratedOnNetFramework()
    {
        const string source = """
            using MessagePack;

            [MessagePackObject]
            public class Sample
            {
                [Key(0)]
                public int Value { get; set; }
            }

            [GeneratedMessagePackResolver]
            public partial class TestResolver
            {
            }
            """;

        // ExcludeFromCodeCoverageAttribute exists on supported .NET Framework targets,
        // so defining NETFRAMEWORK must not suppress decoration.
        var parseOptions = new CSharpParseOptions(LanguageVersion.CSharp12, preprocessorSymbols: new[] { "NETFRAMEWORK" });
        var frameworkReferences = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = frameworkReferences.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "NetFrameworkCoverageExclusionReceipts",
            syntaxTrees: new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references: references,
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out var generatorDiagnostics);
        Assert.True(generatorDiagnostics.IsDefaultOrEmpty, string.Join(Environment.NewLine, generatorDiagnostics));

        GeneratorDriverRunResult runResult = driver.GetRunResult();
        Assert.NotEmpty(runResult.GeneratedTrees);
        int inspectedClasses = 0;
        foreach (SyntaxTree tree in runResult.GeneratedTrees)
        {
            SyntaxNode root = await tree.GetRootAsync();
            foreach (ClassDeclarationSyntax declaration in root.DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                inspectedClasses++;
                bool hasAttribute = declaration.AttributeLists
                    .SelectMany(list => list.Attributes)
                    .Any(attribute => attribute.Name.ToString() == "global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage");
                Assert.True(hasAttribute, $"Generated class {declaration.Identifier.ValueText} in {tree.FilePath} has no ExcludeFromCodeCoverage attribute.");
            }
        }

        Assert.True(inspectedClasses > 0, "The generator did not produce any classes to inspect.");
    }
}
